BEGIN;

-- Logical libraries below one physical connection.
CREATE TABLE "LibraryRoots" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(128) NOT NULL CHECK (length(btrim("Name")) > 0),
    "MediaTypeId" smallint NOT NULL REFERENCES "MediaTypes" ("Id"),
    "MediaSubtypeId" smallint NULL,
    "StorageMountId" bigint NOT NULL REFERENCES "StorageMounts" ("Id") ON DELETE RESTRICT,
    "RelativePath" varchar(1024) NOT NULL CHECK ("RelativePath" NOT LIKE '/%' AND "RelativePath" NOT LIKE '%/'),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("StorageMountId", "RelativePath"),
    FOREIGN KEY ("MediaSubtypeId", "MediaTypeId") REFERENCES "MediaSubtypeParents" ("MediaSubtypeId", "MediaTypeId")
);

-- Wanted targets may name their library (Acquisition is installed first).
ALTER TABLE "WantedItems" ADD FOREIGN KEY ("LibraryRootId") REFERENCES "LibraryRoots" ("Id") ON DELETE SET NULL;
ALTER TABLE "AcquisitionConnections" ADD FOREIGN KEY ("DownloadStorageMountId") REFERENCES "StorageMounts" ("Id") ON DELETE RESTRICT;

-- Inventory survives offline storage; missing files are only marked by complete scans.
CREATE TABLE "StoredFiles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "LibraryRootId" bigint NOT NULL REFERENCES "LibraryRoots" ("Id") ON DELETE CASCADE,
    "RelativePath" varchar(2048) NOT NULL CHECK (length("RelativePath") > 0 AND "RelativePath" NOT LIKE '/%'),
    "SizeBytes" bigint NOT NULL CHECK ("SizeBytes" >= 0),
    "ModifiedAt" timestamptz NOT NULL,
    "MediaAssetId" bigint NULL REFERENCES "MediaAssets" ("Id") ON DELETE SET NULL,
    "LastSeenAt" timestamptz NOT NULL,
    "MissingSince" timestamptz NULL,
    "ProbedAt" timestamptz NULL,
    -- The pages of a comic archive, counted once per version of the file.
    "PageCount" integer NULL CHECK ("PageCount" > 0),
    "PagesCheckedAt" timestamptz NULL,
    "Container" varchar(64) NULL,
    "DurationMs" bigint NULL CHECK ("DurationMs" >= 0),
    "BitRate" bigint NULL CHECK ("BitRate" >= 0),
    "ReleaseLanguages" varchar(16)[] NULL,
    "ReleaseLanguageEvidence" jsonb NULL,
    "Sha1" varchar(40) NULL CHECK ("Sha1" ~ '^[0-9a-f]{40}$'),
    -- What the release name says: group, quality, edition and revision (2 for a proper or repack); the probe reports the streams.
    "ReleaseName" varchar(500) NULL,
    "ReleaseGroup" varchar(64) NULL,
    "QualityKey" varchar(64) NULL,
    "Edition" varchar(64) NULL,
    "Revision" smallint NOT NULL DEFAULT 1 CHECK ("Revision" BETWEEN 1 AND 9),
    "TrickplayFrames" integer NULL CHECK ("TrickplayFrames" > 0),
    "TrickplayCheckedAt" timestamptz NULL,
    "SubtitlesCheckedAt" timestamptz NULL,
    -- Subtitle files by extension, as LibraryFileTypes knows them.
    "IsSubtitle" boolean GENERATED ALWAYS AS ("RelativePath" ~* '\.(srt|ass|ssa|vtt|sub|idx|sup)$') STORED,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("LibraryRootId", "RelativePath")
);
CREATE INDEX "IX_StoredFiles_Asset" ON "StoredFiles" ("MediaAssetId") WHERE "MediaAssetId" IS NOT NULL;
CREATE INDEX "IX_StoredFiles_Unmatched" ON "StoredFiles" ("LibraryRootId", "RelativePath") WHERE "MediaAssetId" IS NULL;

-- Matching stays in CustomFormatMatcher. This evidence view is the common input for cached file matches and live installed-file scores.
CREATE VIEW "StoredFileFormatEvidence" AS
SELECT file."Id" AS "StoredFileId", work."Id" AS "WorkId", asset."WorkUnitId", work."MediaTypeId", file."QualityKey",
    jsonb_build_object(
        'ReleaseName', coalesce(file."ReleaseName", file."RelativePath"),
        'SizeBytes', file."SizeBytes",
        'IndexerFlags', coalesce(release."IndexerFlags", '{}'::varchar[]),
        'Movie', work."MediaTypeId" = 1,
        'MediaTypeId', work."MediaTypeId",
        'OriginalLanguage', work."OriginalLanguage",
        'Year', work."ReleaseYear"
    ) AS "Evidence"
FROM "StoredFiles" AS file
    JOIN "MediaAssets" AS asset ON asset."Id" = file."MediaAssetId"
    JOIN "Works" AS work ON work."Id" = asset."WorkId"
    LEFT JOIN LATERAL (
        SELECT taken."IndexerFlags"
        FROM "AcquisitionReleases" AS taken JOIN "WantedItems" AS wanted ON wanted."Id" = taken."WantedItemId"
        WHERE wanted."WorkId" = work."Id" AND left(taken."Title", 500) = file."ReleaseName"
        ORDER BY taken."Id" DESC LIMIT 1
    ) AS release ON TRUE
WHERE file."MissingSince" IS NULL AND NOT file."IsSubtitle";

CREATE TABLE "StoredFileCustomFormats" (
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "CustomFormatId" bigint NOT NULL REFERENCES "CustomFormats" ("Id") ON DELETE CASCADE,
    "FormatVersion" bigint NOT NULL,
    "Evidence" jsonb NOT NULL,
    "Matches" boolean NOT NULL,
    "IsValid" boolean NOT NULL,
    PRIMARY KEY ("StoredFileId", "CustomFormatId")
);
CREATE INDEX "IX_StoredFileCustomFormats_Format" ON "StoredFileCustomFormats" ("CustomFormatId", "StoredFileId");

-- Profile scores remain a relational sum over the canonical matcher's current results. Score changes need no file rescans.
CREATE VIEW "StoredFileProfileScores" AS
SELECT evidence."StoredFileId", profile."Id" AS "AcquisitionProfileId",
    coalesce(sum((score ->> 'Score')::integer) FILTER (WHERE evaluated."Matches"
        AND evaluated."FormatVersion" = format."Version" AND evaluated."Evidence" = evidence."Evidence"), 0)::integer AS "FormatScore",
    bool_and(score IS NULL OR coalesce(evaluated."FormatVersion" = format."Version" AND evaluated."Evidence" = evidence."Evidence" AND evaluated."IsValid", FALSE)) AS "IsComplete"
FROM "StoredFileFormatEvidence" AS evidence
    JOIN "AcquisitionProfiles" AS profile ON profile."MediaTypeId" = evidence."MediaTypeId"
    LEFT JOIN LATERAL jsonb_array_elements(coalesce(profile."Definition" -> 'FormatScores', '[]'::jsonb)) AS score ON TRUE
    LEFT JOIN "CustomFormats" AS format ON format."Id" = (score ->> 'FormatId')::bigint
    LEFT JOIN "StoredFileCustomFormats" AS evaluated ON evaluated."StoredFileId" = evidence."StoredFileId" AND evaluated."CustomFormatId" = format."Id"
GROUP BY evidence."StoredFileId", profile."Id";

CREATE TABLE "MediaTrackTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "MediaTrackTypes" ("Id", "Key") VALUES (1, 'Video'), (2, 'Audio'), (3, 'Subtitle');

CREATE TABLE "MediaTracks" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "StreamIndex" integer NOT NULL CHECK ("StreamIndex" >= 0),
    "MediaTrackTypeId" smallint NOT NULL REFERENCES "MediaTrackTypes" ("Id"),
    "Codec" varchar(64) NULL,
    "Language" varchar(16) NULL,
    "Title" varchar(256) NULL,
    "Width" integer NULL CHECK ("Width" > 0),
    "Height" integer NULL CHECK ("Height" > 0),
    "Channels" integer NULL CHECK ("Channels" > 0),
    -- Of a video: bits per colour, the dynamic range as the arrs name it (HDR10, DV HDR10, HLG …) and whether it is stereoscopic.
    "BitDepth" smallint NULL CHECK ("BitDepth" BETWEEN 1 AND 32),
    "DynamicRange" varchar(16) NULL CHECK (length(btrim("DynamicRange")) > 0),
    "Is3D" boolean NOT NULL DEFAULT FALSE,
    "IsDefault" boolean NOT NULL,
    "IsForced" boolean NOT NULL,
    UNIQUE ("StoredFileId", "StreamIndex")
);

-- The chapters of a video file as the probe read them, kept whole for the player's chapter menu.
CREATE TABLE "MediaChapters" (
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "ChapterIndex" integer NOT NULL CHECK ("ChapterIndex" >= 0),
    "StartMs" bigint NOT NULL CHECK ("StartMs" >= 0),
    "EndMs" bigint NOT NULL CHECK ("EndMs" >= "StartMs"),
    "Title" varchar(256) NULL,
    PRIMARY KEY ("StoredFileId", "ChapterIndex")
);

-- Stretches of a video file a viewer may skip. One per kind and source; where several sources know the same kind the lowest source id wins (a manual edit before a sidecar, a chapter, a detection).
CREATE TABLE "MediaMarkerKindTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "MediaMarkerKindTypes" ("Id", "Key") VALUES (1, 'Intro'), (2, 'Credits'), (3, 'Recap'), (4, 'Preview');

CREATE TABLE "MediaMarkerSourceTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "MediaMarkerSourceTypes" ("Id", "Key") VALUES (1, 'Manual'), (2, 'Sidecar'), (3, 'Chapter'), (4, 'Detected');

CREATE TABLE "MediaMarkers" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StoredFileId" bigint NOT NULL REFERENCES "StoredFiles" ("Id") ON DELETE CASCADE,
    "MediaMarkerKindTypeId" smallint NOT NULL REFERENCES "MediaMarkerKindTypes" ("Id"),
    "MediaMarkerSourceTypeId" smallint NOT NULL REFERENCES "MediaMarkerSourceTypes" ("Id"),
    "StartMs" bigint NOT NULL CHECK ("StartMs" >= 0),
    "EndMs" bigint NOT NULL,
    "Confidence" numeric(3, 2) NOT NULL DEFAULT 1 CHECK ("Confidence" BETWEEN 0 AND 1),
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CHECK ("EndMs" > "StartMs"),
    UNIQUE ("StoredFileId", "MediaMarkerKindTypeId", "MediaMarkerSourceTypeId")
);

-- Shared background operations.
CREATE TABLE "OperationTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "OperationTypes" ("Id", "Key") VALUES (1, 'LibraryScan'), (2, 'Download'), (3, 'Backup'), (4, 'Job');

CREATE TABLE "OperationStatusTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "OperationStatusTypes" ("Id", "Key") VALUES (1, 'Queued'), (2, 'Running'), (3, 'Completed'), (4, 'Failed');

CREATE TABLE "Operations" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OperationTypeId" smallint NOT NULL REFERENCES "OperationTypes" ("Id"),
    "OperationStatusTypeId" smallint NOT NULL DEFAULT 1 REFERENCES "OperationStatusTypes" ("Id"),
    "LibraryRootId" bigint NULL REFERENCES "LibraryRoots" ("Id") ON DELETE CASCADE,
    "AcquisitionReleaseId" bigint NULL REFERENCES "AcquisitionReleases" ("Id") ON DELETE CASCADE,
    "AcquisitionConnectionId" bigint NULL REFERENCES "AcquisitionConnections" ("Id") ON DELETE SET NULL,
    "ExternalId" varchar(128) NULL,
    "ProgressPercent" smallint NULL CHECK ("ProgressPercent" BETWEEN 0 AND 100),
    "SizeBytes" bigint NULL CHECK ("SizeBytes" >= 0),
    "RemainingBytes" bigint NULL CHECK ("RemainingBytes" >= 0),
    "EtaSeconds" integer NULL CHECK ("EtaSeconds" >= 0),
    "DownloadStateTypeId" smallint NULL CHECK ("DownloadStateTypeId" BETWEEN 1 AND 4),
    "DownloadWaitUntil" timestamptz NULL,
    "RequestedByAccountId" bigint NULL REFERENCES "Accounts" ("Id") ON DELETE SET NULL,
    "ProcessedCount" bigint NOT NULL DEFAULT 0 CHECK ("ProcessedCount" >= 0),
    -- A failed background job is told here until it runs well again or a person dismisses it.
    "WorkerJobKey" varchar(32) NULL REFERENCES "WorkerJobs" ("Key") ON DELETE CASCADE,
    "ErrorKey" varchar(64) NULL,
    "AttentionKey" varchar(64) NULL,
    "AttentionUrl" varchar(2048) NULL CHECK ("AttentionUrl" ~ '^https://'),
    -- A finished download that waits for a person: the files it holds and where Jularr would place them. It is not read again until the person decides.
    "AttentionProposal" jsonb NULL,
    "SourceLinkUrl" varchar(2048) NULL CHECK ("SourceLinkUrl" ~ '^https://'),
    "DismissedAt" timestamptz NULL,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "StartedAt" timestamptz NULL,
    "FinishedAt" timestamptz NULL,
    CHECK ("OperationTypeId" <> 1 OR "LibraryRootId" IS NOT NULL),
    CHECK ("OperationTypeId" <> 2 OR "AcquisitionReleaseId" IS NOT NULL),
    CHECK (("OperationTypeId" = 4) = ("WorkerJobKey" IS NOT NULL)),
    CHECK ("OperationTypeId" <> 4 OR "OperationStatusTypeId" = 4),
    CHECK (("OperationStatusTypeId" IN (3, 4)) = ("FinishedAt" IS NOT NULL)),
    CHECK ("OperationStatusTypeId" = 4 OR "ErrorKey" IS NULL),
    CHECK ("OperationStatusTypeId" IN (1, 2) OR "AttentionKey" IS NULL),
    CHECK ("AttentionUrl" IS NULL OR "AttentionKey" IS NOT NULL),
    CHECK ("AttentionProposal" IS NULL OR "AttentionKey" IS NOT NULL),
    CHECK ("OperationStatusTypeId" IN (1, 2) OR "SourceLinkUrl" IS NULL),
    CHECK ("DismissedAt" IS NULL OR "OperationStatusTypeId" = 4),
    CHECK ("OperationTypeId" = 2 OR ("SizeBytes" IS NULL AND "DownloadStateTypeId" IS NULL)),
    CHECK ("OperationTypeId" = 2 OR "DownloadWaitUntil" IS NULL)
);
CREATE UNIQUE INDEX "UX_Operations_ActiveScan" ON "Operations" ("LibraryRootId") WHERE "OperationTypeId" = 1 AND "OperationStatusTypeId" IN (1, 2);
CREATE UNIQUE INDEX "UX_Operations_ActiveBackup" ON "Operations" ("OperationTypeId") WHERE "OperationTypeId" = 3 AND "OperationStatusTypeId" IN (1, 2);
CREATE UNIQUE INDEX "UX_Operations_Download" ON "Operations" ("AcquisitionReleaseId") WHERE "OperationTypeId" = 2;
CREATE UNIQUE INDEX "UX_Operations_OpenJobNotice" ON "Operations" ("WorkerJobKey") WHERE "OperationTypeId" = 4 AND "DismissedAt" IS NULL;
CREATE INDEX "IX_Operations_Queue" ON "Operations" ("OperationTypeId", "OperationStatusTypeId", "CreatedAt", "Id");
CREATE INDEX "IX_Operations_Recent" ON "Operations" ("CreatedAt" DESC, "Id" DESC);

CREATE TABLE "DownloadStorageSettings" (
    "DownloadStorageAreaId" smallint PRIMARY KEY CHECK ("DownloadStorageAreaId" IN (1, 2)),
    "WorkspaceId" uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    "IncompleteStorageMountId" bigint NULL REFERENCES "StorageMounts" ("Id") ON DELETE RESTRICT,
    "IncompletePath" varchar(1024) NULL,
    "IncompleteFilesystemIdentity" varchar(128) NULL,
    "CompleteStorageMountId" bigint NULL REFERENCES "StorageMounts" ("Id") ON DELETE RESTRICT,
    "CompletePath" varchar(1024) NULL,
    "CompleteFilesystemIdentity" varchar(128) NULL,
    "FreeSpaceReserveBytes" bigint NULL CHECK ("FreeSpaceReserveBytes" >= 0),
    "MaxJobBytes" bigint NULL CHECK ("MaxJobBytes" > 0),
    "MaxWorkspaceBytes" bigint NULL CHECK ("MaxWorkspaceBytes" > 0),
    "MaxParallelJobs" smallint NOT NULL DEFAULT 2 CHECK ("MaxParallelJobs" BETWEEN 1 AND 20),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    CHECK (("IncompleteStorageMountId" IS NULL) = ("IncompletePath" IS NULL)),
    CHECK (("IncompleteStorageMountId" IS NULL) = ("IncompleteFilesystemIdentity" IS NULL)),
    CHECK (("IncompleteStorageMountId" IS NULL) = ("CompleteStorageMountId" IS NULL)),
    CHECK (("CompleteStorageMountId" IS NULL) = ("CompletePath" IS NULL)),
    CHECK (("CompleteStorageMountId" IS NULL) = ("CompleteFilesystemIdentity" IS NULL)),
    CHECK (("CompleteStorageMountId" IS NULL) = ("FreeSpaceReserveBytes" IS NULL))
);
INSERT INTO "DownloadStorageSettings" ("DownloadStorageAreaId") VALUES (1), (2);

-- The Admin's names for movie and episode files below a library; '/' separates folders, the last part names the file.
-- A subtype may have a pattern of its own (anime episodes); without one its type's pattern names its files.
CREATE TABLE "NamingPatterns" (
    "Id" smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    "MediaTypeId" smallint NOT NULL REFERENCES "MediaTypes" ("Id") CHECK ("MediaTypeId" IN (1, 2)),
    "MediaSubtypeId" smallint NULL,
    "Pattern" varchar(500) NOT NULL CHECK (length(btrim("Pattern")) > 0),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    FOREIGN KEY ("MediaSubtypeId", "MediaTypeId") REFERENCES "MediaSubtypeParents" ("MediaSubtypeId", "MediaTypeId"),
    UNIQUE NULLS NOT DISTINCT ("MediaTypeId", "MediaSubtypeId")
);
INSERT INTO "NamingPatterns" ("MediaTypeId", "MediaSubtypeId", "Pattern") VALUES
    (1, NULL, '{Title} ({Year})/{Title} ({Year}) [{Quality}]'),
    (2, NULL, '{Title}/Season {Season:00}/{Title} - S{Season:00}E{Episode:00} [{Quality}]'),
    (2, 1, '{Title}/Season {Season:00}/{Title} - S{Season:00}E{Episode:00} [{Quality}]');

-- How names are made of values, like the *arrs' media management: whether illegal characters are replaced and a colon
-- (1 delete, 2 dash, 3 space dash, 4 space dash space, 5 smart, 6 custom), and the folder of season 0.
CREATE TABLE "NamingSettings" (
    "MediaTypeId" smallint PRIMARY KEY REFERENCES "MediaTypes" ("Id") CHECK ("MediaTypeId" IN (1, 2)),
    "ReplacesIllegalCharacters" boolean NOT NULL DEFAULT TRUE,
    "ColonReplacementId" smallint NOT NULL DEFAULT 5 CHECK ("ColonReplacementId" BETWEEN 1 AND 6),
    "CustomColonReplacement" varchar(16) NULL,
    "SpecialsFolder" varchar(60) NULL CHECK (length(btrim("SpecialsFolder")) > 0),
    "Version" bigint NOT NULL DEFAULT 1 CHECK ("Version" > 0),
    CHECK ("ColonReplacementId" <> 6 OR "CustomColonReplacement" IS NOT NULL)
);
INSERT INTO "NamingSettings" ("MediaTypeId", "SpecialsFolder") VALUES (1, NULL), (2, 'Specials');

-- Other versions of the same film, episode, track or volume: same Work, unit, kind and edition, books and comics only
-- in the same format; a game keeps one asset per platform.
CREATE VIEW "MediaAssetSiblings" AS
SELECT
    asset."Id" AS "MediaAssetId",
    other."Id" AS "SiblingMediaAssetId"
FROM
    "MediaAssets" AS asset
    JOIN "WorkVersions" AS version ON version."Id" = asset."WorkVersionId"
    JOIN "MediaAssets" AS other ON other."WorkId" = asset."WorkId"
        AND other."WorkUnitId" IS NOT DISTINCT FROM asset."WorkUnitId"
        AND other."MediaAssetTypeId" = asset."MediaAssetTypeId"
        AND other."Id" <> asset."Id"
    JOIN "WorkVersions" AS otherVersion ON otherVersion."Id" = other."WorkVersionId" AND otherVersion."WorkEditionId" = version."WorkEditionId"
WHERE
    asset."MediaAssetTypeId" <> 5
    AND (
        asset."MediaAssetTypeId" IN (1, 2, 3)
        OR (SELECT lower(substring(min(main."RelativePath") FROM '\.[^./]+$')) FROM "StoredFiles" AS main WHERE main."MediaAssetId" = asset."Id" AND NOT main."IsSubtitle")
            = (SELECT lower(substring(min(main."RelativePath") FROM '\.[^./]+$')) FROM "StoredFiles" AS main WHERE main."MediaAssetId" = other."Id" AND NOT main."IsSubtitle")
    );

-- What a title is for a profile: here with a present file or in Plex, requested while searched or asked for by the profile, otherwise not requested.
CREATE VIEW "ProfileWorkStates" AS
SELECT
    profile."Id" AS "ProfileId",
    work."Id" AS "WorkId",
    CASE
        WHEN EXISTS (
            SELECT
                1
            FROM
                "MediaAssets" AS asset
                JOIN "StoredFiles" AS file ON file."MediaAssetId" = asset."Id" AND file."MissingSince" IS NULL
            WHERE
                asset."WorkId" = work."Id"
        ) OR EXISTS (
            SELECT
                1
            FROM
                "WorkExternalIdentities" AS plex
            WHERE
                plex."WorkId" = work."Id"
                AND plex."Namespace" = 'plex'
        ) THEN 3
        WHEN EXISTS (
            SELECT
                1
            FROM
                "WantedItems" AS wanted
            WHERE
                wanted."WorkId" = work."Id"
        ) OR EXISTS (
            SELECT
                1
            FROM
                "AcquisitionRequests" AS request
            WHERE
                request."WorkId" = work."Id"
                AND request."RequestedByProfileId" = profile."Id"
                AND request."AcquisitionRequestStatusTypeId" BETWEEN 1 AND 5
        ) THEN 2
        ELSE 1
    END::smallint AS "MediaStateTypeId"
FROM
    "Profiles" AS profile
    CROSS JOIN "Works" AS work;

-- Files Jularr moved into a recycle folder; only these are ever cleaned up there.
CREATE TABLE "RecycledFiles" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StorageMountId" bigint NOT NULL REFERENCES "StorageMounts" ("Id") ON DELETE CASCADE,
    -- The recycle folder below the connection, and the file below that folder.
    "FolderPath" varchar(2048) NOT NULL CHECK ("FolderPath" NOT LIKE '/%'),
    "RelativePath" varchar(2048) NOT NULL CHECK (length("RelativePath") > 0 AND "RelativePath" NOT LIKE '/%'),
    "RecycledAt" timestamptz NOT NULL DEFAULT now(),
    UNIQUE ("StorageMountId", "FolderPath", "RelativePath")
);
CREATE INDEX "IX_RecycledFiles_Age" ON "RecycledFiles" ("RecycledAt");

-- Targets and monitored units whose best file needs a quality or format-score upgrade.
-- The Wanted list and automatic searches share this state; selection rechecks candidates with UpgradePolicy.
CREATE VIEW "WantedUnitsBelowCutoff" AS
SELECT wanted."Id" AS "WantedItemId", asset."WorkUnitId"
FROM "WantedItems" AS wanted
    JOIN "Works" AS work ON work."Id" = wanted."WorkId"
    JOIN LATERAL (
        SELECT candidate."Id", candidate."Definition"
        FROM "AcquisitionProfiles" AS candidate
        WHERE candidate."MediaTypeId" = work."MediaTypeId"
            AND (candidate."Id" = wanted."AcquisitionProfileId"
                OR wanted."AcquisitionProfileId" IS NULL AND candidate."IsDefault"
                    AND (candidate."MediaSubtypeId" IS NULL OR candidate."MediaSubtypeId" = work."MediaSubtypeId"))
        ORDER BY candidate."MediaSubtypeId" IS NULL
        LIMIT 1
    ) AS profile ON TRUE
    JOIN "MediaAssets" AS asset ON asset."WorkId" = work."Id"
    JOIN "StoredFiles" AS available ON available."MediaAssetId" = asset."Id" AND available."MissingSince" IS NULL
    JOIN jsonb_array_elements_text(profile."Definition" -> 'QualityOrder') WITH ORDINALITY AS quality ("Key", "Position")
        ON lower(quality."Key") = lower(available."QualityKey")
        OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(coalesce(profile."Definition" -> 'QualityGroups', '[]'::jsonb)) AS grouped
                CROSS JOIN jsonb_array_elements_text(grouped -> 'Qualities') AS member ("Key")
            WHERE 'group:' || (grouped ->> 'Id') = quality."Key"
                AND lower(member."Key") = lower(available."QualityKey")
        )
    LEFT JOIN "WorkUnits" AS unit ON unit."Id" = asset."WorkUnitId"
    LEFT JOIN "StoredFileProfileScores" AS scores ON scores."StoredFileId" = available."Id" AND scores."AcquisitionProfileId" = profile."Id"
    CROSS JOIN LATERAL (
        SELECT EXISTS (
            SELECT 1 FROM "RequestTargets" AS target
                JOIN "AcquisitionRequests" AS request ON request."Id" = target."AcquisitionRequestId"
                JOIN "UiLocales" AS locale ON locale."Id" = request."UiLocaleId"
            WHERE target."WantedItemId" = wanted."Id" AND request."AcquisitionRequestStatusTypeId" BETWEEN 2 AND 6
                AND lower(split_part(locale."Locale", '-', 1)) = ANY(available."ReleaseLanguages")
        ) AS "IsRequestedLanguage"
    ) AS preferred
WHERE (profile."Definition" ->> 'UpgradeAllowed')::boolean
    AND (unit."Id" IS NULL OR unit."IsMonitored")
    AND (wanted."GamePlatformId" IS NULL OR EXISTS (
        SELECT 1 FROM "GameReleases" AS game
        WHERE game."WorkVersionId" = asset."WorkVersionId" AND game."GamePlatformId" = wanted."GamePlatformId"
    ))
GROUP BY wanted."Id", asset."WorkUnitId", profile."Definition", work."MediaTypeId", work."MediaSubtypeId"
HAVING min(quality."Position") > coalesce((
    SELECT cutoff."Position"
    FROM jsonb_array_elements_text(profile."Definition" -> 'QualityOrder') WITH ORDINALITY AS cutoff ("Key", "Position")
    WHERE lower(cutoff."Key") = lower(profile."Definition" ->> 'UpgradeCutoffQuality')
    LIMIT 1
), 1)
OR bool_and(coalesce(scores."IsComplete", FALSE))
    AND (array_agg(scores."FormatScore" ORDER BY quality."Position", scores."FormatScore" DESC))[1]
        < coalesce((profile."Definition" ->> 'CutoffFormatScore')::integer, 0)
OR work."MediaTypeId" = 3 AND work."MediaSubtypeId" IS DISTINCT FROM 2
    AND EXISTS (
        SELECT 1 FROM "RequestTargets" AS target
            JOIN "AcquisitionRequests" AS request ON request."Id" = target."AcquisitionRequestId"
        WHERE target."WantedItemId" = wanted."Id" AND request."AcquisitionRequestStatusTypeId" BETWEEN 2 AND 6
    )
    AND NOT (array_agg(preferred."IsRequestedLanguage" ORDER BY quality."Position", scores."FormatScore" DESC, preferred."IsRequestedLanguage" DESC))[1];

CREATE VIEW "WantedBelowCutoff" AS SELECT DISTINCT "WantedItemId" FROM "WantedUnitsBelowCutoff";

-- What happened to a Work's media, for the administrators' history and a requester's steps.
CREATE TABLE "ActivityEventTypes" (
    "Id" smallint PRIMARY KEY,
    "Key" varchar(32) NOT NULL UNIQUE
);
INSERT INTO "ActivityEventTypes" ("Id", "Key") VALUES
    (1, 'Grabbed'), (2, 'DownloadFailed'), (3, 'Imported'), (4, 'Upgraded'), (5, 'FileRenamed'), (6, 'FileDeleted'), (7, 'ManualImport'), (8, 'Blocked'),
    (9, 'SubtitleDownloaded'), (10, 'WorkDeleted');

-- Only ever added. The texts keep an event readable after its Work, release, file or connection is gone; the history's days and size bound it.
CREATE TABLE "ActivityEvents" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ActivityEventTypeId" smallint NOT NULL REFERENCES "ActivityEventTypes" ("Id"),
    "OccurredAt" timestamptz NOT NULL DEFAULT now(),
    "WorkId" bigint NULL REFERENCES "Works" ("Id") ON DELETE SET NULL,
    "WorkUnitId" bigint NULL REFERENCES "WorkUnits" ("Id") ON DELETE SET NULL,
    "AcquisitionReleaseId" bigint NULL REFERENCES "AcquisitionReleases" ("Id") ON DELETE SET NULL,
    "StoredFileId" bigint NULL REFERENCES "StoredFiles" ("Id") ON DELETE SET NULL,
    -- Who did it; none is Jularr itself.
    "AccountId" bigint NULL REFERENCES "Accounts" ("Id") ON DELETE SET NULL,
    "WorkTitle" varchar(500) NOT NULL CHECK (length(btrim("WorkTitle")) > 0),
    "WorkUnitTypeId" smallint NULL REFERENCES "WorkUnitTypes" ("Id"),
    "ParentUnitNumber" numeric(9, 3) NULL,
    "UnitNumber" numeric(9, 3) NULL,
    "ReleaseTitle" varchar(1000) NULL,
    "QualityKey" varchar(64) NULL,
    "IndexerName" varchar(128) NULL,
    "ClientName" varchar(128) NULL,
    "Path" varchar(2048) NULL,
    "PreviousPath" varchar(2048) NULL,
    "ReasonKey" varchar(64) NULL
);
CREATE INDEX "IX_ActivityEvents_Recent" ON "ActivityEvents" ("OccurredAt" DESC, "Id" DESC);
CREATE INDEX "IX_ActivityEvents_Work" ON "ActivityEvents" ("WorkId", "OccurredAt" DESC) WHERE "WorkId" IS NOT NULL;

COMMIT;
